import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M13 12h1c.55 0 1-.45 1-1V8h-3v3c0 .55.45 1 1 1M10 2c0-.55-.45-1-1-1H8c-.55 0-1 .45-1 1v3h3zm0 4H7v3h3zm5-4c0-.55-.45-1-1-1h-1c-.55 0-1 .45-1 1v2h3zm0 3h-3v2h3zM5 5H2v3h3zm-2 7h1c.55 0 1-.45 1-1V9H2v2c0 .55.45 1 1 1m12 1H2c-.55 0-1 .45-1 1s.45 1 1 1h13c.55 0 1-.45 1-1s-.45-1-1-1M5 2c0-.55-.45-1-1-1H3c-.55 0-1 .45-1 1v2h3zm3 10h1c.55 0 1-.45 1-1v-1H7v1c0 .55.45 1 1 1"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M15 16h2c.55 0 1-.45 1-1v-5h-4v5c0 .55.45 1 1 1M12 2c0-.55-.45-1-1-1H9c-.55 0-1 .45-1 1v4h4zm6 4h-4v3h4zm0-4c0-.55-.45-1-1-1h-2c-.55 0-1 .45-1 1v3h4zm-6 5H8v5h4zm-9 9h2c.55 0 1-.45 1-1v-3H2v3c0 .55.45 1 1 1m6 0h2c.55 0 1-.45 1-1v-2H8v2c0 .55.45 1 1 1m10 1H1c-.55 0-1 .45-1 1s.45 1 1 1h18c.55 0 1-.45 1-1s-.45-1-1-1M6 2c0-.55-.45-1-1-1H3c-.55 0-1 .45-1 1v3h4zm0 4H2v5h4z"] as readonly string[];

export const FullStackedChartIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="full-stacked-chart" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
FullStackedChartIcon.displayName = `Blueprint6.Icon.FullStackedChartIcon`;

/**
 * @deprecated Use {@link FullStackedChartIcon} instead.
 */
export const FullStackedChart: typeof FullStackedChartIcon = FullStackedChartIcon;

export default FullStackedChartIcon;
